package com.anthony6996.hardcorecompass.listener;
import com.anthony6996.hardcorecompass.manager.CompassManager;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.PrepareItemCraftEvent;
public final class CompassCraftListener implements Listener{private final CompassManager compasses;public CompassCraftListener(CompassManager c){compasses=c;}@EventHandler public void onPrepare(PrepareItemCraftEvent e){if(e.getRecipe()==null)return;Player p=e.getView().getPlayer() instanceof Player player?player:null;if(compasses.isCompassRecipe(e.getRecipe()))e.getInventory().setResult(compasses.createCompass(null,p));else if(compasses.isLodestoneRecipe(e.getRecipe()))e.getInventory().setResult(compasses.createLodestone(p));}}
